class Mergesort 
{ 
    void merge(int arr[], int l, int m, int r) 
    { 
        int n1 = m - l + 1; 
        int n2 = r - m; 

        int L[] = new int[n1]; 
        int R[] = new int[n2]; 

        for (int i = 0; i < n1; ++i) 
            L[i] = arr[l + i]; 
        for (int j = 0; j < n2; ++j) 
            R[j] = arr[m + 1 + j]; 

        int i = 0, j = 0; 

        int k = l; 
        while (i < n1 && j < n2) { 
            if (L[i] <= R[j]) { 
                arr[k] = L[i]; 
                i++; 
            } 
            else { 
                arr[k] = R[j]; 
                j++; 
            } 
            k++; 
        } 

        while (i < n1) { 
            arr[k] = L[i]; 
            i++; 
            k++; 
        } 

        while (j < n2) { 
            arr[k] = R[j]; 
            j++; 
            k++; 
        } 
    } 

    void sort(int arr[], int l, int r) 
    { 
        if (l < r) { 
            int m = (l + r) / 2; 

            sort(arr, l, m); 
            sort(arr, m + 1, r); 

            merge(arr, l, m, r); 
        } 
    } 
}

function validateCreditCardNumber(number) {
    // remove any spaces or dashes
    number = number.replace(/\s/g, ""); // remove any spaces
    number = number.replace(/-/g, ""); // remove any dashes
    // check for valid credit card length
    if (number.length != 16) {
        return false;
    }
    // check that each number is a valid number
    for (let i = 0; i < 15; i++) {
        let n = parseInt(number[i]);
        if (isNaN(n)) {
            return false;
        }
    }
    // validate the credit card
    let sum = 0;
    for (let i = 0; i < 15; i++) {
        let n = parseInt(number[i]);
        if (i % 2 == 0) {
            n *= 2;
            if (n > 9) { 
                n = (n % 10) + 1;
            }
        }
        sum += n;
    }
    let last = parseInt(number[15]);
    let check = 10 - (sum % 10);
    return last == check;
}

