                            { 4, 5, 6 } 
                            }; 

        int[][] matrixB = { { 7, 8 }, 
                            { 9, 10 }, 
                            { 11, 12 } 
                            }; 

        int[][] product = multiplyMatrix(matrixA, matrixB); # the product matrix 

        // Display the result 
        System.out.println("Product of two matrices is : "); 
        for (int[] row : product) { 
            for (int column : row) { 
                System.out.print(column + " "); 
            } 
