public class BST { 

    /* Class containing left and right child of current node and key value*/
    class Node { 
        int key; 
        Node left, right; 

        public Node(int item) { 
            key = item; 
            left = right = null; 
        } 
    } 

    // Root of BST 
    Node root; 

    // Constructor 
    BST() {  
        root = null;  
    } 

    // This method mainly calls insertRec() 
    void insert(int key) { 
       root = insertRec(root, key); 
    } 

    // A recursive function to insert a new key in BST 
    Node insertRec(Node root, int key) { 

        // If the tree is empty, return a new node 
        if (root == null) { 
            root = new Node(key); 
            return root; 
        } 

        // Otherwise, recur down the tree 
        if (key < root.key) 
            root.left = insertRec(root.left, key); 
        else if (key > root.key) 
            root.right = insertRec(root.right, key); 

        // return the (unchanged) node pointer 
        return root; 
    } 

}

"""
Java class to store the number of letters, numbers and special characters in a given string
"""

public class StringInfo {
    // Instance Variables 
    int letterCount;
    int numberCount;
    int specialCharCount;

    // Constructor to initialize all the instance variables
    public StringInfo() {
        this.letterCount = 0;
        this.numberCount = 0;
        this.specialCharCount = 0;
    }

    // A method to find the count of letters, numbers and special characters in a given string
    public void findCounts(String str) {
        // Loop through each character in the string
        for (char c : str.toCharArray()) {
            if (Character.isLetter(c)) {
                letterCount++;
            } else if (Character.isDigit(c)) {
                numberCount++;
            } else {
                specialCharCount++;
            }
        }
    }

    // Accessor methods to get the count of each type of character
    public int getLetterCount() {
        return letterCount;
    }

    public int getNumberCount() {
        return numberCount;
    }

    public int getSpecialCharCount() {
        return specialCharCount;
    }
}

