public class MyStack {
    int top; 
    int[] stackArray; 

    // Constructor to initialize 
    public MyStack(int capacity) { 
        stackArray = new int[capacity]; 
        top = -1; 
    } 

    // Push an element to the top of the stack
    public void push(int data) { 
        stackArray[++top] = data; 
    } 

    // Pop an element from the top of the stack 
    public int pop() { 
        return stackArray[top--]; 
    } 

    // peek or peak an element from the top of the stack 
    public int peek() { 
        return stackArray[top]; 
    } 

    // Check if the stack is empty 
    public boolean isEmpty() { 
        return (top == -1); 
    } 

    // Return the size of the stack 
    public int size() { 
        return top + 1; 
    } 
}

def longest_increasing_sequence(arr):
    lengths = [1]*len(arr)

    for i in range(1, len(arr)):
        for j in range(i):
            if arr[i] > arr[j]:
                lengths[i] = max(lengths[i], lengths[j] + 1)

    max_length_index = 0
    for i in range(len(lengths)):
        if lengths[i] > lengths[max_length_index]:
            max_length_index = i

    current_index = max_length_index
    sequence = [arr[max_length_index]]
    for i in range(max_length_index-1, -1, -1):
        if lengths[i] == lengths[current_index] - 1 and arr[i] < arr[current_index]:
            sequence.append(arr[i])
            current_index = i
    sequence.reverse()
    return sequence

