public static int[] intersection(int[] arr1, int[] arr2) 
{ 
    // Initialise array to store intersection 
    int[] result = new int[arr1.length]; 

    // Initialise two index in both array 
    int i = 0, j = 0; 

    // Initially set intersection index 
    int k = 0; 

    // Sort both array 
    Arrays.sort(arr1); 
    Arrays.sort(arr2); 

    // Iterate over both array and store intersection 
    // in array result 
    while (i < arr1.length && j < arr2.length)  
    { 
        // If both current element are same 
        if (arr1[i] == arr2[j])  
        { 
            // Store it in result array 
            result[k++] = arr1[i++]; 
            j++; 
        } 
        // If first array current element is smaller 
        else if (arr1[i] < arr2[j]) 
            i++; 
        // If second array current element is smaller 
        else
            j++; 
    } 

    // return the result array 
    return Arrays.copyOfRange(result, 0, k); 
}

int compareToFindSmallest(int[] numbers, int targetIndex) {

    int smallestIndex = 0;
    for (int i = 1; i < numbers.length; i++) 
    {
        if (numbers[i] < numbers[smallestIndex]) {
            smallestIndex = i;
        }
    }

    int tempIndex = smallestIndex;
    int resultIndex = -1;
    int count = 0;
    while (resultIndex == -1) {
        count++;
        if (smallestIndex == tempIndex) {
            if (count == targetIndex) {
                resultIndex = tempIndex;
            }
            tempIndex++;
        } else {
            if (numbers[tempIndex] == numbers[smallestIndex]) {
                if (count == targetIndex) {
                    resultIndex = tempIndex;
                }
                tempIndex++;
            } else {
                smallestIndex = tempIndex;
            }
        }

        if (tempIndex >= numbers.length) {
            tempIndex = smallestIndex + 1;
        }
    }

    return resultIndex;
}

