class RollingAverage {
  private:
    int windowSize;
    int currentIndex;
    double total;
    std::vector<double> data;

  public:
    RollingAverage(int windowSize)
        : windowSize(windowSize)
        , currentIndex(0)
        , total(0.0)
        , data(windowSize) 
    { 
        for (int i = 0; i < windowSize; ++i) {
            data.push_back(0.0);
        }
    }

    void add(double value) {
        int prevIndex = (currentIndex - 1 + windowSize) % windowSize;
        total -= data[prevIndex];
        total += value;
        data[currentIndex] = value;
        currentIndex = (currentIndex + 1) % windowSize;
    }

    double getAverage() {
        return total / windowSize;
    }
};

function deleteDuplicates(str) {  
  let result = ""; 
  let frequency = {}; 

  // creating a map of all characters with their frequency in the string 
  for (let i = 0; i < str.length; i++) { 
    let currentChar = str.charAt(i); 
    if (frequency[currentChar]) { 
      frequency[currentChar]++; 
    } else { 
      frequency[currentChar] = 1; 
    } 
  } 

  // adding only those characters which have frequency greater than one 
  for (let i = 0; i < str.length; i++) { 
    let currentChar = str.charAt(i); 
    if (frequency[currentChar] == 1) { 
      result += str.charAt(i); 
    } 
  } 

  return result; 
}

