    // Find the maximum number to know number of digits 
    int max = getMax(arr, n); 

    // Do counting sort for every digit. Note that instead 
    // of passing digit number, exp is passed. exp is 10^i 
    // where i is current digit number 
    for (int exp = 1; max/exp > 0; exp *= 10) 
        countSort(arr, n, exp); 
} 

int getMax(int arr[], int n) 
{ 
    int max = arr[0]; 
    for (int i = 1; i < n; i++) 
        if (arr[i] > max) 
            max = arr[i]; 
    return max; 
} 

void countSort(int arr[], int n, int exp) 
{ 
    int output[n]; // output array 
    int i; 
    int count[10] = {0}; 

    // Store count of occurrences in count[] 
    for (i = 0; i < n; i++) 
        count[ (arr[i]/exp)%10 ]++; 

    // Change count[i] so that count[i] now contains actual 
    //  position of this digit in output[] 
    for (i = 1; i < 10; i++) 
        count[i] += count[i - 1]; 

    // Build the output array 
    for (i = n - 1; i >= 0; i--) 
    { 
        output[count[ (arr[i]/exp)%10 ] - 1] = arr[i]; 
        count[ (arr[i]/exp)%10 ]--; 
    } 

    // Copy the output array to arr[], so that arr[] now 
    // contains sorted numbers according to curent digit 
    for (i = 0; i < n; i++) 
        arr[i] = output[i]; 
}

public static boolean isBalanced(String str) 
{ 
    if(str.length() == 0) 
        return true; 

    Stack<Character> stack  = new Stack<Character>(); 

    for(int i = 0; i < str.length(); i++) 
    { 
        char current = str.charAt(i); 

        if(current == '{' || current == '(' || current == '[') 
        { 
        stack.push(current); 
        } 

        if(current == '}' || current == ')' || current == ']') 
        { 
            if(stack.isEmpty()) 
                return false; 

            char last = stack.peek(); 
            if(current == '}' && last == '{' || current == ')' && last == '(' || current == ']' && last == '[') 
                stack.pop(); 
            else 
                return false; 
        }
    } 

    return stack.isEmpty(); 
}

public static List<int[]> findSumPairs(int[] arr, int target) {
    List<int[]> pairs = new ArrayList<>();

    Map<Integer, Integer> numFreqMap = new HashMap<>();
    for (int value : arr) {
        numFreqMap.put(value, numFreqMap.getOrDefault(value, 0) + 1);
    }

    for (int value : arr) {
        int targetSubValue = target - value;

        if (numFreqMap.containsKey(targetSubValue)) {
            int targetSubValueFreq = numFreqMap.get(targetSubValue);

            if (targetSubValue == value) {
                if (targetSubValueFreq >= 2) {
                    int[] pair = {value, targetSubValue};
                    pairs.add(pair);
                }
            } else {
                int[] pair = {value, targetSubValue};
                pairs.add(pair);
            }

            numFreqMap.put(targetSubValue, 0);
        }
    }

    return pairs;
}

