// Function to sort given array  
void sort(int arr[], int n)  
{  
    int i, j;  
    for (i = 0; i < n-1; i++)      

    // Last i elements are already in place  
    for (j = 0; j < n-i-1; j++)  
        if (arr[j] > arr[j+1])  
            swap(arr[j], arr[j+1]);  
}  

/* Function to swap two numbers */
void swap(int *a, int *b)  
{  
    int temp = *a;  
    *a = *b;  
    *b = temp;  
}  
int main()  
{  
    int arr[] = {4,3,7,2,9,6};  
