public class InsertionSort { 
	public static void inplaceInsertionSort(int[] array) { 
		// Iterate over array elements 
		for (int i = 1; i < array.length; i++) { 
			int value = array[i]; 
			int j = i; 
			// Check whether the adjacent element in 
			// left side is greater or not 
			while (j > 0 && array[j - 1] > value) { 
				// shifting the elements 
				array[j] = array[j - 1]; 
				j--; 
			} 
			// moving the element in right side 
			array[j] = value; 
		} 
	} 
	// Driver Code 
	public static void main(String[] args) { 
		int[] arr = { 20, 12, 10, 15, 2 }; 
		inplaceInsertionSort(arr); 
		for (int i : arr) { 
			System.out.print(i + " "); 
		} 

	}

def edit_strings(s1, s2):
    s1_arr = list(s1)
    s2_arr = list(s2)

    i = 0
    while i < len(s1):
        if s1[i] == s2[i]:
            i += 1
        else:
            # remove character
            del s1_arr[i]
            if s1_arr == s2_arr:
                return 'removal'
            # insert character
            s1_arr.insert(i, s2[i])
            if s1_arr == s2_arr:
                return 'insertion'
            # replace character
            s1_arr[i] = s2[i]
            if s1_arr == s2_arr:
                return 'replacement'
            break
    return None

def is_valid_isbn_10(code):
    # check for the length
    if len(code) != 10:
        return False
    # check for leading "X" characters
    if code.startswith("X"):
        return False
    # check for digits
    if not code.isdigit():
        return False
    # calculate the check digit
    sum = 0
    for i in range(9): 
        sum += int(code[i]) * (10 - i)
    checksum = sum % 11
    # check for valid check digit
    if not (checksum==int(code[9]) or (checksum == 10 and code[9] == 'X')):
        return False
    # No errors found
    return True

if __name__ == '__main__':
    code = input('Enter the ISBN-10 code: ')
    print(is_valid_isbn_10(code))

// Function to remove comments from a given input string
string removeComments(string input_string)
{
    string output_string = "";
    int flag = 0;

    for (int i = 0; i<input_string.length(); i++)
    {
        // Check for single line comments
        if (input_string[i] == '/' && input_string[i+1] == '/')
            flag = 1;

        // Check for multi-line comments
        if (input_string[i] == '/' && input_string[i+1] == '*')
            flag = 2;

        // If single line or multi-line comment section,
        // ignore the part of the string
        if (flag == 1 || flag == 2)
        {
            if (input_string[i] == '\n')
                flag = 0;
            continue;
        }

        output_string += input_string[i];
    }

    return output_string;
}

def rot13(message):
    output = []
    for char in message:
        char_code = ord(char)
        if char_code >= ord('A') and char_code <= ord('Z'):
            # Rotate lower case characters
            char_code += 13
            if char_code > ord('Z'):
                char_code -= 26
        elif char_code >= ord('a') and char_code <= ord('z'):
            # Rotate upper case characters
            char_code += 13
            if char_code > ord('z'):
                char_code -= 26
        output.append(chr(char_code))
    return ''.join(output)
print(rot13("Hello World"))

function splitStringWithDelimiters (string, delimiters) { 
  let result = []; 
  let s = string; 
  while (s.length > 0) { 
    let char = s[0]; 
    if (delimiters.includes(char)) { 
      s = s.substr(1); 
    } else { 
      let index = 0; 
      for (const delimiter of delimiters) { 
        if (s.indexOf(delimiter) > 0 && s.indexOf(delimiter) < index) { 
          index = s.indexOf(delimiter); 
        } 
      } 
      if (index === 0) { 
        index = s.length; 
      } 
      result.push(s.substr(0, index)); 
      s = s.substr(index); 
    } 
  } 
  return result; 
}

