def partition(array, begin, end):
    pivot = begin
    for i in range(begin+1, end+1):
        if array[i] <= array[begin]:
            pivot += 1
            array[i], array[pivot] = array[pivot], array[i]
    array[pivot], array[begin] = array[begin], array[pivot]
    return pivot

def quick_sort(array, begin=0, end=None):
    if end is None:
        end = len(array) - 1

    def _quick_sort(array, begin, end):
        if begin >= end:
            return
        pivot = partition(array, begin, end)
        _quick_sort(array, begin, pivot-1)
        _quick_sort(array, pivot+1, end)

    return _quick_sort(array, begin, end)

function quicksort(input_array) {
    if (input_array.length <= 1) {
        return input_array;
    }

    const pivot = input_array[0];
    const left = [];
    const right = [];

    for (let i = 1; i < input_array.length; i++) {
        if (input_array[i] < pivot) {
            left.push(input_array[i]);
        } else {
            right.push(input_array[i]);
        }
    }

    return [...quicksort(left), pivot, ...quicksort(right)];
}

