// bucket sort
function bucketSort(arr) {
  let buckets = new Array(arr.length); 
  let result = []; 

  for (let i = 0; i < arr.length; i++) {
    buckets[i] = 0;
  }

  for (let i = 0; i < arr.length; i++) {
    buckets[arr[i]]++;
  }

  for (let i = 0; i < arr.length; i++) {
    while (buckets[i] > 0) {
      result.push(i);
      buckets[i]--;
    }
  }

  return result;
}

def longest_substring(string):
    curr_len = 1
    max_len = 1
    prev_index = 0
    n = len(string)
    visited = [-1] * 256
    visited[ord(string[0])] = 0
    for i in range(1,n):
        prev_index = visited[ord(string[i])]
        if prev_index == -1 or (i - curr_len > prev_index):
            curr_len+=1
        else:
            if curr_len > max_len:
                max_len = curr_len
            curr_len = i - prev_index
        visited[ord(string[i])] = i
    if curr_len > max_len:
        max_len = curr_len
    return max_len

def sum_n_fibonacci_numbers(num):
    """This function takes in a number, n, and sums
    the first n Fibonacci numbers.

    Parameters
    ----------
    num : int
        The number of Fibonacci numbers to sum.

    Returns
    -------
    The sum of the first n Fibonacci numbers.
    """

    fib = [0, 1]
    if num < 0:
        return None
    elif num == 0:
        return 0
    elif num == 1:
        return 1
    else:
        for i in range(2, num + 1):
            fib.append(fib[i-2] + fib[i-1])
        return sum(fib)

