def sublist_sum(numbers, target) : 
    n = len(numbers) 

    # Consider all sublists of arr[] and return 
    # true if given sum is present in any of them 
    for i in range(n) : 
        curr_sum = numbers[i] 

        # Try different endpoints for current subarray 
        j = i+1
        while j<=n : 

            if curr_sum == target : 
                return True

            if curr_sum > target or j == n: 
                break

            curr_sum = curr_sum + numbers[j] 
            j += 1

    return False

class HistoryDataStruct:
    def __init__(self, k):
        self.history_size = k
        self.history = [] # list of (undo command, state of only that undo command) of size k
        self.current_state = None # Current state of the data structure

    def save_states(self, state):
        self.history.append((state, self.current_state))

        if len(self.history) > self.history_size:
            self.history.pop(0)

        self.current_state = state

    def undo(self):
        command, prev_state = self.history[-1]
        self.history.pop(-1)
        self.current_state = prev_state
        return command

def levenshteinDistance(word1, word2):
  m = len(word1)
  n = len(word2)

  dp = [[0 for i in range(n + 1)] for j in range(m + 1)] 

  for i in range(m + 1): 
    for j in range(n + 1): 
      if i == 0: 
        dp[i][j] = j

      elif j == 0: 
        dp[i][j] = i

      elif word1[i - 1] == word2[j - 1]: 
        dp[i][j] = dp[i - 1][j - 1] 

      else: 
        dp[i][j] = 1 + min(dp[i][j - 1],  
                            dp[i - 1][j],  
                            dp[i - 1][j - 1]) 

  return dp[m][n]

