public static String longestCommonSubsequence(String s1,String s2) {
   int l1 = s1.length();
   int l2 = s2.length();

   int[][] aux = new int[l1+1][l2+1];
   for (int i = 0; i < l1; i++) {
      for (int j = 0; j < l2; j++) {
         if (s1.charAt(i) == s2.charAt(j))
            aux[i+1][j+1] = aux[i][j] + 1;
         else
            aux[i+1][j+1] = Math.max(aux[i+1][j], aux[i][j+1]);
      }
   }
   StringBuilder sb = new StringBuilder();
   for (int i = l1, j = l2; i != 0 && j != 0; ) {
      if (aux[i][j] == aux[i-1][j])
         i--;
      else if (aux[i][j] == aux[i][j-1])
         j--;
      else {
         sb.append(s1.charAt(i-1));
         i--;
         j--;
      }
   }
   return sb.reverse().toString();
}

class Vector3d {
    double x, y, z;

    //Constructor
    Vector3d(double x, double y, double z) {
        this.x = x;
        this.y = y;
        this.z = z;
    }

    // Dot product
    double dotProduct(Vector3d vec2) {
        double result = this.x * vec2.x + this.y * vec2.y + this.z * vec2.z;
        return result;
    }

    // Normalization
    Vector3d normalize() {
        double magnitude = Math.sqrt(this.x * this.x + this.y * this.y + this.z * this.z);
        Vector3d normalized = new Vector3d(this.x / magnitude, this.y / magnitude, this.z / magnitude);
        return normalized;
    }
}

