def convert_to_base(num, base): 
    """ 
    Function to convert num to a given base 
    """
    converted_string = "" 

    # Base Case 
    if num < base: 
        if num < 10: 
            return str(num) 
        else: 
            return chr(num - 10 + ord('A')) 

    rem = num % base 
    if rem < 10: 
        converted_string = str(rem) + converted_string 
    else: 
        converted_string = chr(rem - 10 + ord('A')) + converted_string 
    num = num // base 
    return convert_to_base(num, base) + converted_string

def find_max_subseq(str1, str2):
    n1 = len(str1)
    n2 = len(str2)
    dp = [[0 for _ in range(n2 + 1)] for _ in range(n1 + 1)]

    for i in range(1, n1 + 1):
        for j in range(1, n2 + 1):
            if(str1[i - 1] == str2[j - 1]):
                dp[i][j] = dp[i - 1][j - 1] + 1 
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])
    return dp[n1][n2]

