function heapSort(arr) {
 let n = arr.length;

 for (let i = Math.floor(n / 2 - 1); i >= 0; i--) {
 heapify(arr, n, i);
 }

 for (let i = n - 1; i > 0; i--) {
 [arr[0], arr[i]] = [arr[i], arr[0]];
 heapify(arr, i, 0);
 }

 return arr;
}

function heapify(arr, n, i) {
 let largest = i;
 let left = 2 * i + 1;
 let right = 2 * i + 2;

 if (left < n && arr[left] > arr[largest])
 largest = left;

 if (right < n && arr[right] > arr[largest])
 largest = right;

 if (largest !== i) {
 [arr[i], arr[largest]] = [arr[largest], arr[i]];
 heapify(arr, n, largest);
 }
}

function areAnagrams(str1, str2) {
  if (str1.length !== str2.length) {
    return false;
  }
  let charMap1 = {};
  let charMap2 = {};

  for(let i = 0; i < str1.length; i++) {
    if(!charMap1[str1.charAt(i)]) {
      charMap1[str1.charAt(i)] = 1;
    } else { 
      charMap1[str1.charAt(i)]++;
    }

    if(!charMap2[str2.charAt(i)]) {
      charMap2[str2.charAt(i)] = 1;
    } else { 
      charMap2[str2.charAt(i)]++;
    }
  }

  for(let key in charMap1) {
    if (charMap1[key] != charMap2[key]) {
      return false;
    }
  }

  return true;

}

