def multiply_matrices(A, B):
    if len(A[0]) != len(B):
        raise ValueError("Matrices cannot be multiplied")

    rows_A = len(A)
    columns_A = len(A[0])
    rows_B = len(B)
    columns_B = len(B[0])

    result = [[0 for column in range(columns_B)] for row in range(rows_A)]

    for row in range(rows_A):
