bool areEqual (std::array<std::array<int,2>,2> first, std::array<std::array<int,2>,2> second )
{
    if( first.size() != second.size() )
        return false;

    for(int i = 0; i <  first.size(); i++)
    {
        for(int j = 0; j < first[i].size(); j++)
        {
            if( first[i][j] != second[i][j] )
