using namespace std;

char highest_frequency(string str)
{
    unordered_map<char, int> char_count;
    for (char &c : str)
    {
        char_count[c]++;
    }
    char max_char = ' ';
    int max_count = 0;
    for (auto &c : char_count)
    {
        int temp_count = c.second;
        if (temp_count > max_count)
        {
            max_count = temp_count;
            max_char = c.first;
        }
    }
    return max_char;

}

int main()
{
    string str = "This is a sample string!";
    cout << highest_frequency(str) << endl;
    return 0;
}

function findWords(str) { 
    let words = []; 
    let start = 0; 

    for (let i = 0; i < str.length; i++) { 
        if (str[i] == ' ') { 
            let word = str.substring(start, i); 
            if (word != '') 
                words.push(word); 
            start = i + 1; 
        } 
    } 

    let lastWord =  str.substring(start, str.length); 
    if (lastWord != '') 
        words.push(lastWord); 

    return words; 
}

