function mergeArrays(A, B) {
  let merged = [];
  let indexA = 0;
  let indexB = 0;
  while (indexA < A.length && indexB < B.length) {
    merged.push(A[indexA], B[indexB]);
    indexA++;
    indexB++;
  }
  if (indexA < A.length) {
    for (let i=indexA; i < A.length; i++) {
      merged.push(A[i]);
    }
  }
  if (indexB < B.length) {
    for (let i=indexB; i < B.length; i++) {
      merged.push(B[i]);
    }
  }
  return merged;
}

public class Reverse {

    public static void main(String[] args) {

        String str = "Hello World";

        // Output is reversed string
        System.out.println(reverseString(str));
    }

    public static String reverseString(String str)
    {
        StringBuilder strBuilder = new StringBuilder();
        char[] strChars = str.toCharArray();

        for (int i = strChars.length - 1; i >= 0; i--) {
            strBuilder.append(strChars[i]);
        }

        return strBuilder.toString();
    }
}

"""
Write a code to convert a given English sentence into Pig Latin.
"""

def pig_latin(sentence):
    vowel = ["a", "e", "i", "o", "u"]
    words = sentence.split(" ")
    pig_latin_words = []

    for word in words:
        if word[0] in vowel:
            pig_latin_words.append(word + "way")
        else:
            pig_latin_words.append(word[1:] + word[0] + "ay")

    return " ".join(pig_latin_words)

if __name__ == "__main__":
    sentence = "This is a sample sentence"
    print(pig_latin(sentence))

void selectionSort(int arr[], int n) 
{ 
    int i, j, min_idx; 

    // One by one move boundary of unsorted subarray 
    for (i = 0; i < n-1; i++) 
    { 
        // Find the minimum element in unsorted array 
        min_idx = i; 
        for (j = i+1; j < n; j++) 
        {
            if (arr[j] < arr[min_idx]) 
            {
                min_idx = j; 
            }
        } 

        // Swap the found minimum element with the first 
        // element 
        swap(&arr[min_idx], &arr[i]); 
    } 
}

