int is_same_quadrant(int x1, int y1, int x2, int y2) 
{ 
    //determining quadrants for coordinates
    int q1 = (y1 >= 0) ? (x1 >= 0 ? 1 : 2) : (x1 >= 0 ? 4 : 3); 
    int q2 = (y2 >= 0) ? (x2 >= 0 ? 1 : 2) : (x2 >= 0 ? 4 : 3); 

    // If both the coordinates 
    // belongs to same quadrants 
    // then returns 1 
    return (q1 == q2); 
} 

