"""
A code to find the longest common prefix among a given set of strings
"""

def longest_common_prefix(strs): 

    if not strs: 
        return "" 

    shortest_str = min(strs,key=len) 

    for i, ch in enumerate(shortest_str): 
        for other in strs: 
            if other[i] != ch: 
                return shortest_str[:i]  
    return shortest_str 

if __name__ == '__main__': 
    strs = ["flower","flow","flight"] 
    print("The longest common prefix is: %s" % longest_common_prefix(strs))

public class Fibonacci {
    public static void main(String args[]) {
        int n = 10;
        int a = 0, b = 1, c;
        if (n == 1)
            System.out.println("Fibonacci of " + n + " is " + a);
        else {
            for (int i = 2; i <= n; i++) {
                c = a + b;
                a = b;
                b = c;
            }
            System.out.println("Fibonacci of " + n + " is " + b);
        }
    }
}
